import pandas as pd
import numpy as np
import re
from sklearn.ensemble import ExtraTreesRegressor, RandomForestRegressor, GradientBoostingRegressor
from sklearn.neighbors import KNeighborsRegressor

df = pd.read_csv('/work/b3_supercon_data.csv')

def parse_formula(formula):
    pattern = r'([A-Z][a-z]?)(\d*\.?\d*)'
    matches = re.findall(pattern, formula)
    counts = {}
    for el, num in matches:
        n = float(num) if num else 1.0
        counts[el] = counts.get(el, 0) + n
    return counts

def to_fractions(counts):
    total = sum(counts.values())
    return {k: v/total for k, v in counts.items()}

elems = ['O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni']
bounds = {
    'O': (0, 0.697674), 'Cu': (0, 0.454545), 'Ba': (0, 0.333333),
    'Sr': (0, 0.285714), 'Y': (0, 0.4), 'Ca': (0, 0.272727),
    'La': (0, 0.78), 'Bi': (0, 0.521978), 'Fe': (0, 0.502513),
    'Nb': (0, 0.98), 'C': (0, 0.972), 'Pr': (0, 0.265043),
    'As': (0, 0.5), 'B': (0, 1), 'Pb': (0, 0.5),
    'Ce': (0, 0.28), 'Mo': (0, 1), 'V': (0, 0.9918),
    'Zn': (0, 1), 'Ni': (0, 0.6),
}
lo = np.array([bounds[e][0] for e in elems])
hi = np.array([bounds[e][1] for e in elems])
idx = {e:i for i,e in enumerate(elems)}

rows = []
for i, row in df.iterrows():
    counts = parse_formula(row['composition'])
    fracs = to_fractions(counts)
    rec = [fracs.get(e, 0.0) for e in elems]
    rows.append(rec)
X = np.array(rows)
y = df['target'].values.astype(float)

et = ExtraTreesRegressor(n_estimators=500, min_samples_leaf=1, random_state=0)
rf = RandomForestRegressor(n_estimators=400, min_samples_leaf=1, random_state=1)
gb = GradientBoostingRegressor(n_estimators=400, max_depth=3, random_state=2)
knn = KNeighborsRegressor(n_neighbors=5, weights='distance')
et.fit(X, y); rf.fit(X, y); gb.fit(X, y); knn.fit(X, y)

def pred_ensemble(Xp):
    return (et.predict(Xp) + rf.predict(Xp) + gb.predict(Xp) + knn.predict(Xp)) / 4

def make_x(d):
    x = np.zeros(20)
    for e,v in d.items():
        x[idx[e]] = v
    return np.clip(x, lo, hi)

def robust_eval(x, relative=True, also_range=False):
    x = np.array(x, dtype=float)
    pts = [x.copy()]
    labels = ['base']
    for i in range(len(x)):
        for s in (-1, 1):
            x2 = x.copy()
            if relative:
                if abs(x[i]) < 1e-12:
                    continue
                x2[i] = x[i] * (1 + 0.05 * s)
            else:
                x2[i] = x[i] + s * 0.05 * (hi[i] - lo[i])
            x2[i] = np.clip(x2[i], lo[i], hi[i])
            pts.append(x2)
            labels.append(f'{elems[i]}{"+" if s>0 else "-"}5%')
    P = np.vstack(pts)
    mu = pred_ensemble(P)
    return mu[0], mu.min(), labels[int(np.argmin(mu))], mu

# Grid search around top families
rng = np.random.default_rng(42)

candidates = []

# Family 1: Hg-1223 like O~0.5, Cu~0.15-0.22, Ba~0.10-0.20, Ca~0.08-0.18
for O in np.linspace(0.45, 0.58, 8):
    for Cu in np.linspace(0.14, 0.25, 8):
        for Ba in np.linspace(0.08, 0.22, 8):
            for Ca in np.linspace(0.08, 0.20, 7):
                candidates.append(make_x({'O':O,'Cu':Cu,'Ba':Ba,'Ca':Ca}))

# Family 2: Ba-Ca-Cu-O low oxygen
for O in np.linspace(0.08, 0.20, 7):
    for Cu in np.linspace(0.28, 0.42, 8):
        for Ba in np.linspace(0.15, 0.30, 7):
            for Ca in np.linspace(0.15, 0.27, 7):
                candidates.append(make_x({'O':O,'Cu':Cu,'Ba':Ba,'Ca':Ca}))

# Family 3: Tl/Pb-1223 like
for O in np.linspace(0.08, 0.20, 5):
    for Cu in np.linspace(0.28, 0.40, 6):
        for Ba in np.linspace(0.10, 0.25, 6):
            for Sr in np.linspace(0.0, 0.10, 4):
                for Ca in np.linspace(0.15, 0.27, 5):
                    for Pb in np.linspace(0.0, 0.08, 3):
                        candidates.append(make_x({'O':O,'Cu':Cu,'Ba':Ba,'Sr':Sr,'Ca':Ca,'Pb':Pb}))

# Family 4: BSCCO
for O in list(np.linspace(0.08, 0.16, 4)) + list(np.linspace(0.50, 0.60, 4)):
    for Cu in np.linspace(0.10, 0.32, 6):
        for Sr in np.linspace(0.10, 0.22, 5):
            for Ca in np.linspace(0.05, 0.22, 5):
                for Bi in np.linspace(0.08, 0.22, 5):
                    for Pb in [0.0, 0.03, 0.05]:
                        candidates.append(make_x({'O':O,'Cu':Cu,'Sr':Sr,'Ca':Ca,'Bi':Bi,'Pb':Pb}))

# Family 5: infinite layer Ca-Sr-Cu-O
for O in np.linspace(0.45, 0.55, 6):
    for Cu in np.linspace(0.20, 0.30, 6):
        for Sr in np.linspace(0.10, 0.22, 6):
            for Ca in np.linspace(0.04, 0.15, 6):
                candidates.append(make_x({'O':O,'Cu':Cu,'Sr':Sr,'Ca':Ca}))

# Family 6: mix Hg1223 + Sr
for O in np.linspace(0.48, 0.54, 4):
    for Cu in np.linspace(0.16, 0.22, 4):
        for Ba in np.linspace(0.08, 0.16, 4):
            for Sr in np.linspace(0.0, 0.08, 4):
                for Ca in np.linspace(0.08, 0.16, 4):
                    candidates.append(make_x({'O':O,'Cu':Cu,'Ba':Ba,'Sr':Sr,'Ca':Ca}))

# Random around top 10 training points
top_idx = np.argsort(-y)[:15]
for ti in top_idx:
    x0 = X[ti]
    for _ in range(80):
        noise = rng.normal(0, 0.02, size=20)
        # only perturb elements that are active or cuprate-relevant
        mask = np.zeros(20)
        mask[:8] = 1  # O Cu Ba Sr Y Ca La Bi
        mask[idx['Pb']] = 1
        mask[idx['Ca']] = 1
        x2 = np.clip(x0 + noise*mask, lo, hi)
        # keep toxic elems 0 if originally 0
        for e in ['Fe','Nb','C','Pr','As','B','Ce','Mo','Zn','Ni','La']:
            if x0[idx[e]] < 1e-8:
                x2[idx[e]] = 0
        candidates.append(x2)

C = np.vstack(candidates)
print('candidates', C.shape)

# batch predict
chunk = 5000
base_preds = []
for i in range(0, len(C), chunk):
    base_preds.append(pred_ensemble(C[i:i+chunk]))
base_preds = np.concatenate(base_preds)

# take top 400 by base pred and compute robust
top = np.argsort(-base_preds)[:400]
print('top base pred', base_preds[top[0]], base_preds[top[399]])

results = []
for j in top:
    x = C[j]
    p0, pmin, worst, _ = robust_eval(x)
    results.append((pmin, p0, worst, x))

results.sort(key=lambda t: (-t[0], -t[1]))
print('\nTop 20 by robust_min:')
for pmin, p0, worst, x in results[:20]:
    used = {elems[i]: round(x[i],4) for i in range(20) if x[i]>1e-6}
    print(f'  pred={p0:6.2f} rmin={pmin:6.2f} worst={worst:10s} {used}')

print('\nTop 10 by 0.5*pred+0.5*rmin:')
results2 = sorted(results, key=lambda t: -(0.5*t[0]+0.5*t[1]))
for pmin, p0, worst, x in results2[:10]:
    used = {elems[i]: round(x[i],4) for i in range(20) if x[i]>1e-6}
    print(f'  pred={p0:6.2f} rmin={pmin:6.2f} worst={worst:10s} {used}')
